-- SLBI Growth & Security OS / SmartSearch Multilingual Dictionary v1.
-- Curated aliases only; no private query history or user data.
-- This is a controlled, read-only public search taxonomy with review gates.
CREATE TABLE IF NOT EXISTS public.search_dictionary (
 id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 alias TEXT NOT NULL CHECK (char_length(alias) BETWEEN 2 AND 120),
 alias_normalized TEXT GENERATED ALWAYS AS (lower(btrim(regexp_replace(alias, '[[:space:]]+', ' ', 'g')))) STORED,
 language TEXT NOT NULL CHECK (language IN ('en','ta','si','ta-Latn','si-Latn','mixed')),
 alias_kind TEXT NOT NULL CHECK (alias_kind IN ('location','category','service')),
 intent_key TEXT NOT NULL,
 canonical_query TEXT NOT NULL CHECK (char_length(canonical_query) BETWEEN 2 AND 100),
 categories TEXT[] NOT NULL DEFAULT '{}',
 specific_service BOOLEAN NOT NULL DEFAULT FALSE,
 town_name TEXT,
 confidence SMALLINT NOT NULL DEFAULT 95 CHECK(confidence BETWEEN 0 AND 100),
 source TEXT NOT NULL DEFAULT 'slbi_curated_initial_v1',
 review_status TEXT NOT NULL DEFAULT 'draft' CHECK (review_status IN ('approved','draft','rejected')),
 is_active BOOLEAN NOT NULL DEFAULT TRUE,
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 CONSTRAINT slbi_search_dictionary_alias_key UNIQUE (alias_normalized, alias_kind),
 CONSTRAINT slbi_search_dictionary_location_shape CHECK (
   (alias_kind='location' AND town_name IS NOT NULL AND cardinality(categories)=0 AND NOT specific_service)
   OR
   (alias_kind<>'location' AND town_name IS NULL)
 )
);
ALTER TABLE public.search_dictionary ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.search_dictionary FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.search_dictionary TO anon, authenticated;
DO $policy$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='search_dictionary' AND policyname='public_can_read_approved_search_dictionary') THEN
 CREATE POLICY public_can_read_approved_search_dictionary
 ON public.search_dictionary FOR SELECT TO anon, authenticated
 USING (review_status='approved' AND is_active);
 END IF;
END $policy$;
CREATE INDEX IF NOT EXISTS search_dictionary_enabled_idx
 ON public.search_dictionary(alias_kind,language,intent_key)
 WHERE review_status='approved' AND is_active;

