INSERT INTO public.search_dictionary
 (alias,language,alias_kind,intent_key,canonical_query,categories,specific_service,town_name,confidence,source,review_status)
SELECT
 value->>'alias', value->>'language', value->>'alias_kind',value->>'intent_key',
 value->>'canonical_query',
 ARRAY(SELECT jsonb_array_elements_text(value->'categories')),
 COALESCE((value->>'specific_service')::BOOLEAN,FALSE),
 NULLIF(value->>'town_name',''),
 COALESCE((value->>'confidence')::SMALLINT,95),
 value->>'source',
 value->>'review_status'
FROM payload
ON CONFLICT (alias_normalized,alias_kind) DO NOTHING;
